$ErrorActionPreference = 'Stop'
$testRoot = Split-Path -Parent $PSScriptRoot
$testPython = '<BUNDLED_RUNTIME>\python\python.exe'
$repo = '<TESTED_CHECKOUT>'
Push-Location $testRoot
try {
    & git --no-optional-locks -c safe.directory=<TESTED_CHECKOUT> -C $repo status --porcelain=v1 > "$PSScriptRoot\rerun-git-before.txt"
    & git -c safe.directory=<TESTED_CHECKOUT> -C $repo rev-parse HEAD > "$PSScriptRoot\rerun-head.txt"
    foreach ($testMode in @('inventory','core','routes','p3','asgi')) {
        $logOut = "$PSScriptRoot\rerun-$testMode-stdout.log"
        $logErr = "$PSScriptRoot\rerun-$testMode-stderr.log"
        $testProc = Start-Process -FilePath $testPython -ArgumentList @('-B',"$PSScriptRoot\security_runner.py",$testMode) -WorkingDirectory $testRoot -WindowStyle Hidden -RedirectStandardOutput $logOut -RedirectStandardError $logErr -PassThru
        $testWatch = [Diagnostics.Stopwatch]::StartNew()
        while (-not $testProc.WaitForExit(100)) {
            $testProc.Refresh()
            if ($testWatch.Elapsed.TotalSeconds -gt 60 -or $testProc.WorkingSet64 -gt 268435456) {
                Stop-Process -Id $testProc.Id
                throw "$testMode exceeded 60 seconds or 256 MiB working set. Only this test process was stopped."
            }
        }
        Write-Output "$testMode exit=$($testProc.ExitCode); logs: $logOut $logErr"
        if ($testProc.ExitCode -ne 0) { throw "$testMode failed; inspect its logs." }
    }
    & git --no-optional-locks -c safe.directory=<TESTED_CHECKOUT> -C $repo status --porcelain=v1 > "$PSScriptRoot\rerun-git-after.txt"
    Compare-Object (Get-Content "$PSScriptRoot\rerun-git-before.txt") (Get-Content "$PSScriptRoot\rerun-git-after.txt")
} finally { Pop-Location }

