import sys, os, pathlib, json, time, unittest, importlib, ctypes, hashlib, tempfile
ROOT = pathlib.Path(r'<TESTED_CHECKOUT>')
BASE = pathlib.Path(__file__).resolve().parent.parent
TEMP = BASE / 'work' / 'test-temp'
TEMP.mkdir(exist_ok=True)
os.environ['TMP'] = os.environ['TEMP'] = str(TEMP)
tempfile.tempdir = str(TEMP)
sys.dont_write_bytecode = True
sys.path[:0] = [str(ROOT), str(ROOT/'custody-service/src'), str(ROOT/'custody-service/tests'), str(ROOT/'.venv/Lib/site-packages')]
blocked = []
loopback_operations = []
def writable(p):
    if isinstance(p, int): return
    p = pathlib.Path(os.fsdecode(p)).resolve()
    if not p.is_relative_to(BASE):
        blocked.append({'operation':'write', 'path':str(p)})
        raise PermissionError('Test write outside evidence workspace blocked')
def audit(event, args):
    if event == 'open':
        p, mode, flags = args
        if (mode and any(x in mode for x in 'wax+')) or (flags and flags & (os.O_WRONLY|os.O_RDWR|os.O_CREAT|os.O_TRUNC|os.O_APPEND)): writable(p)
    elif event == 'sqlite3.connect' and args[0] != ':memory:': writable(args[0])
    elif event in ('os.remove','os.rmdir','os.mkdir','os.chmod','os.utime','os.symlink'): writable(args[0])
    elif event in ('os.rename','os.replace'): writable(args[0]); writable(args[1])
    elif event in ('subprocess.Popen','os.system'):
        blocked.append({'operation':event}); raise PermissionError('Child execution blocked')
    elif event in ('socket.connect','socket.bind'):
        addr=args[1]
        if isinstance(addr,tuple) and addr[0] not in ('127.0.0.1','::1'):
            blocked.append({'operation':event,'address':str(addr)}); raise PermissionError('Non-loopback network blocked')
        elif isinstance(addr,tuple): loopback_operations.append({'operation':event,'address':addr})
sys.addaudithook(audit)
class PMC(ctypes.Structure):
    _fields_=[('cb',ctypes.c_ulong),('faults',ctypes.c_ulong)]+[(n,ctypes.c_size_t) for n in ['peak_ws','ws','peak_paged','paged','peak_nonpaged','nonpaged','pagefile','peak_pagefile']]
def memory():
    p=PMC(); p.cb=ctypes.sizeof(p)
    if not ctypes.windll.psapi.GetProcessMemoryInfo(ctypes.c_void_p(-1),ctypes.byref(p),p.cb):
        raise ctypes.WinError()
    return {'working_set_bytes':p.ws,'peak_working_set_bytes':p.peak_ws,'private_bytes':p.pagefile}
start=time.perf_counter(); cpu=time.process_time(); initial=memory()
mode=sys.argv[1]
summary={'mode':mode,'initial_memory':initial,'blocked_operations':blocked,'loopback_operations':loopback_operations}
if mode == 'inventory':
    from importlib.metadata import distributions
    from packaging.requirements import Requirement
    ds=list(distributions(path=[str(ROOT/'.venv/Lib/site-packages')]))
    installed={d.metadata['Name'].lower().replace('_','-'):d.version for d in ds}
    rows=[]; mismatches=[]
    for d in ds:
        reqs=d.requires or []; rows.append({'name':d.metadata['Name'],'version':d.version,'requires':reqs})
        for s in reqs:
            r=Requirement(s)
            if r.marker and not r.marker.evaluate({'extra':''}): continue
            v=installed.get(r.name.lower().replace('_','-'))
            if v is None or (r.specifier and not r.specifier.contains(v)): mismatches.append({'package':d.metadata['Name'],'requirement':s,'installed':v})
    summary.update(packages=rows,dependency_conflicts=mismatches,manifest_drift={'uvicorn':{'declared':'0.52.4','installed':installed.get('uvicorn')},'anyio':{'declared_test':'4.14.2','installed':installed.get('anyio')},'httpx2':{'declared_test':'2.12.0','installed':installed.get('httpx2')},'sentry-traffic':{'declared':'0.1.0','installed':installed.get('sentry-traffic')},'cryptography':{'declared_optional':'50.0.1','installed':installed.get('cryptography')},'mcp':{'declared_optional':'>=2,<3','installed':installed.get('mcp')}})
    print(json.dumps(summary,indent=2))
elif mode == 'core':
    names=['tests.test_kernel','tests.test_authority','tests.test_persistence','tests.test_execution_context_binding','tests.test_github_execution_context','tests.test_custody_executor','tests.test_custody_domain','tests.test_transport_security','tests.test_network_exposure','tests.test_issue_153_consequence_reconciliation_v0.Issue153ConsequenceReconciliationV0.test_05_replay_substitution_expiry_revocation_and_widening_do_not_create_fresh_authority']
    result=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromNames(names))
    summary.update(tests=result.testsRun,failures=len(result.failures),errors=len(result.errors),skips=result.skipped)
elif mode == 'routes':
    mod=importlib.import_module('tests.test_mcp_boundary')
    names=[f'tests.test_mcp_boundary.MCPBoundaryTests.{n}' for n in dir(mod.MCPBoundaryTests) if n.startswith('test_') and 'export' not in n]
    result=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromNames(names))
    summary.update(tests=result.testsRun,failures=len(result.failures),errors=len(result.errors),skips=result.skipped)
elif mode == 'p3':
    sys.path.insert(0,str(pathlib.Path(__file__).resolve().parent))
    result=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromName('p3_security_tests'))
    summary.update(tests=result.testsRun,failures=len(result.failures),errors=len(result.errors),skips=result.skipped)
elif mode == 'asgi':
    import ast, types, asyncio
    class Response:
        def __init__(self,status,body): self.status_code=status; self.text=body.decode()
        def json(self): return json.loads(self.text)
    class DirectClient:
        def __init__(self,app): self.app=app
        def post(self,path,**kwargs):
            payload=json.dumps(kwargs.get('json',{})).encode()
            async def request():
                sent=[]; supplied=False
                async def receive():
                    nonlocal supplied
                    if not supplied: supplied=True; return {'type':'http.request','body':payload,'more_body':False}
                    await asyncio.sleep(10)
                    return {'type':'http.disconnect'}
                async def send(event): sent.append(event)
                scope={'type':'http','asgi':{'version':'3.0'},'http_version':'1.1','method':'POST','scheme':'http','path':path,'raw_path':path.encode(),'query_string':b'','root_path':'','headers':[(b'content-type',b'application/json')],'client':('127.0.0.1',12345),'server':('127.0.0.1',80)}
                await asyncio.wait_for(self.app(scope,receive,send),3)
                status=next(e['status'] for e in sent if e['type']=='http.response.start')
                body=b''.join(e.get('body',b'') for e in sent if e['type']=='http.response.body')
                print('ASGI_RESPONSE '+json.dumps({'path':path,'status':status}))
                return Response(status,body)
            return asyncio.run(request())
    source=ROOT/'custody-service/tests/test_api.py'
    tree=ast.parse(source.read_text(encoding='utf-8'))
    tree.body=[n for n in tree.body if not (isinstance(n,ast.ImportFrom) and n.module=='fastapi.testclient')]
    module=types.ModuleType('isolated_api_tests'); module.__dict__['TestClient']=DirectClient
    sys.modules[module.__name__]=module
    exec(compile(tree,str(source),'exec'),module.__dict__)
    summary['adaptation']='Original API tests loaded in memory; TestClient import replaced by direct real-app ASGI invocation. No httpx2, server, or lifespan exercised.'
    result=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromModule(module))
    summary.update(tests=result.testsRun,failures=len(result.failures),errors=len(result.errors),skips=result.skipped)
summary.update(wall_seconds=time.perf_counter()-start,cpu_seconds=time.process_time()-cpu,final_memory=memory())
(BASE/'outputs'/f'{mode}-summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')
print('METRICS '+json.dumps(summary if mode != 'inventory' else {k:v for k,v in summary.items() if k!='packages'}))
sys.exit(0 if mode=='inventory' or (not summary['failures'] and not summary['errors']) else 1)
